Urgent: Facing this issue in the implementation of face recognition on the webcam camera for the browser. This error only comes when I add more than 1 name in my labels in loadLabeledImages() function. If I have one name, it works perfectly fine. Any help is appreciated. This is a part of a project that has to be completed in a week!
Thank you so much!

Getting "Uncaught (in promise) TypeError: Cannot read property 'descriptor' of undefined"
![image](https://user-images.githubusercontent.com/35863027/79368026-d3c8e300-7f5f-11ea-9901-5a209eadf3e0.png)

This is the code for your reference:

`

```
 const video = document.getElementById('video')
 
 Promise.all([
   faceapi.nets.tinyFaceDetector.loadFromUri('/models'),
   faceapi.nets.faceLandmark68Net.loadFromUri('/models'),
   faceapi.nets.faceRecognitionNet.loadFromUri('/models'),
   faceapi.nets.ssdMobilenetv1.loadFromUri('/models'),
 ]).then(startVideo)


```
```
function startVideo() {
  navigator.getUserMedia(
    { video: {} },
    stream => video.srcObject = stream,
    err => console.error(err)
  )
}

this.video.addEventListener('play',() => {
  const canvas = faceapi.createCanvasFromMedia(video)
  document.body.append(canvas)
  const displaySize = { width: video.width, height: video.height }
  faceapi.matchDimensions(canvas, displaySize)
  setInterval(async () => {
    const detections = await faceapi.detectAllFaces(video).withFaceLandmarks().withFaceDescriptors()
    const resizedDetections = faceapi.resizeResults(detections, displaySize)
    canvas.getContext('2d').clearRect(0, 0, canvas.width, canvas.height)
    faceapi.draw.drawFaceLandmarks(canvas, resizedDetections)
    this.labeledFaceDescriptors = await this.loadLabeledImages()
    const faceMatcher = new faceapi.FaceMatcher(labeledFaceDescriptors, 0.6)
    const results = resizedDetections.map(d => faceMatcher.findBestMatch(d.descriptor))
    results.forEach((result, i) => {
      const box = resizedDetections[i].detection.box
      const drawBox = new faceapi.draw.DrawBox(box, {label: result.toString()})
      drawBox.draw(canvas) 
    })

  }, 100) 
})

function loadLabeledImages() {

  try{
    const labels = ['Shriya', 'judhi']

    return Promise.all(
      labels.map(async label => {
        const descriptions = []
        for (let i = 1; i <= 3; i++) {
          const img = await faceapi.fetchImage(`public/img/${label}/${i}.jpg`)
          const detections = await faceapi.detectSingleFace(img).withFaceLandmarks().withFaceDescriptor()
          descriptions.push(detections.descriptor)
        }
  
        return new faceapi.LabeledFaceDescriptors(label, this.descriptions)
      })
    )

  }
  catch(err){
    console.log(err)
  }

}`
```

I have been trying to get this to work in an Angular component, without success, and would love a bit of help/direction. Await dies on the vine and I'm stumped as to what to do next beyond throwing more darts at the wall. Is there a debug flag somewhere?

**[package.json]**
"face-api.js": "^0.18.0",

**[component.html]**
< div style="position: relative" class="margin">
  < video id="videoEl" autoplay muted>< /video>
  < canvas id="overlay">< /canvas>
< /div>

**[component.ts]**
import { Component, OnInit } from '@angular/core';

import * as $ from 'jquery';

// implements nodejs wrappers for HTMLCanvasElement, HTMLImageElement, ImageData
import * as canvas from 'canvas';
import * as faceapi from 'face-api.js';
import { CPU_ENVS } from '@tensorflow/tfjs-core/dist/test_util';

// patch nodejs environment, we need to provide an implementation of
// HTMLCanvasElement and HTMLImageElement, additionally an implementation
// of ImageData is required, in case you want to use the MTCNN
const { Canvas, Image, ImageData } = canvas;
faceapi.env.monkeyPatch({ Canvas, Image, ImageData });

const TINY_FACE_DETECTOR = 'tiny_face_detector';

@Component({
  selector: 'app-facetrack',
  templateUrl: './facetrack.component.html',
  styleUrls: ['./facetrack.component.css']
})
export class FacetrackComponent implements OnInit {

  // tiny_face_detector options
  inputSize = 512;
  scoreThreshold = 0.5;
  withFaceLandmarks = false;
  withBoxes = true;
  videoEl;
  stream;

  constructor(
  ) {
  }

  ngOnInit() {
    this.loadModels();
  }

  // ======================================================================
  // BEGIN: startTracking
  // ======================================================================
  async startTracking() {
    let cnvs;
    const vEl = <HTMLCanvasElement>document.getElementById('videoEl');
    const vElwidth = vEl.width;
    const vElheight = vEl.height;
    console.log('start tracking...');
    const options = new faceapi.TinyFaceDetectorOptions({ inputSize: 320, scoreThreshold: 0.5 });

    const ts = Date.now();

    setTimeout(function () {

      console.log('this.videoEl = ' + vEl);
      // const detections = faceapi.detectSingleFace(vEl).withFaceLandmarks();
      const detections = faceapi.detectSingleFace(vEl, options);
      console.log('detections');
      console.log(detections);

      // resize the detected boxes in case your displayed image has a different size then the original
      const detectionsForSize = faceapi.resizeResults(detections, { width: vElwidth, height: vElheight });
      console.log('detectionsForSize');
      console.log(detectionsForSize);
      // draw them into a canvas
      cnvs = document.getElementById('overlay');
      // this.canvas.getContext('2d');
      canvas.width = vEl.width;
      canvas.height = vEl.height;
      faceapi.drawDetection(cnvs, detectionsForSize, { withScore: true });

    }, 5000);

  }
  // ======================================================================
  // END: startTracking
  // ======================================================================

  // ======================================================================
  // BEGIN: cameraConnect
  // ======================================================================
  async cameraConnect() {
    // try to access users webcam and stream the images
    // to the video element
    this.stream = await navigator.mediaDevices.getUserMedia({ video: {} });
    this.videoEl = $('#videoEl').get(0);
    this.videoEl.srcObject = this.stream;

    if (this.videoEl.srcObject.active === true) {
      this.startTracking();
    } else {
      console.log('Camera not connected...');
    }

  }
  // ======================================================================
  // END: cameraConnect
  // ======================================================================

  // ======================================================================
  // BEGIN: loadModels
  // ======================================================================
  async loadModels() {
    // load the models
    await faceapi.loadTinyFaceDetectorModel('./assets/weights/');
    await faceapi.loadFaceRecognitionModel('./assets/weights/');
    this.cameraConnect();
  }
  // ======================================================================
  // END: loadModels
  // ======================================================================

}

